import { act, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
  callServerTool: vi.fn().mockResolvedValue({ isError: false }),
  close: vi.fn(),
  connect: vi.fn().mockResolvedValue(undefined),
  hostContext: {} as Record<string, unknown>,
  listeners: new Map<string, Set<(params: any) => void>>(),
}));
vi.mock("@modelcontextprotocol/ext-apps", () => ({
  App: class {
    addEventListener(name: string, handler: (params: any) => void) { const hs = bridge.listeners.get(name) ?? new Set(); hs.add(handler); bridge.listeners.set(name, hs); }
    removeEventListener(name: string, handler: (params: any) => void) { bridge.listeners.get(name)?.delete(handler); }
    callServerTool = bridge.callServerTool;
    connect = bridge.connect;
    getHostContext() { return { theme: "light", ...bridge.hostContext }; }
    async openLink() { return { isError: false }; }
  },
  PostMessageTransport: class { close = bridge.close; },
}));
const originalParent = Object.getOwnPropertyDescriptor(window, "parent");
const originalOpenai = Object.getOwnPropertyDescriptor(window, "openai");
beforeEach(() => { vi.resetModules(); vi.clearAllMocks(); bridge.listeners.clear(); bridge.callServerTool.mockResolvedValue({isError:false}); });
afterEach(() => { if (originalParent) Object.defineProperty(window, "parent", originalParent); if (originalOpenai) Object.defineProperty(window, "openai", originalOpenai); else Reflect.deleteProperty(window, "openai"); });

it("review: preserves capability when compat full delivery precedes metadata-less standard delivery", async () => {
  const parent = Object.assign(new EventTarget(), { location: { origin: "https://chatgpt.com" } });
  Object.defineProperty(window, "parent", { configurable: true, value: parent });
  let resolveRestore!: (value: any) => void;
  const restore = new Promise<any>((resolve) => { resolveRestore = resolve; });
  bridge.callServerTool.mockImplementation(async ({name}: any) => name === "restore_lobu_app_result" ? restore : ({isError:false, structuredContent:{saved:true}}));
  const { Provider, useMcpApp } = await import("./host");
  function Probe() { const {data, viewState} = useMcpApp<{title:string}>(); return <><span>{data?.title}</span><span>open:{String(viewState["details.open"])}</span></>; }
  render(<Provider devMock={{title:"dev"}}><Probe/></Provider>);
  await waitFor(() => expect(bridge.connect).toHaveBeenCalled());
  act(() => window.dispatchEvent(new CustomEvent("openai:set_globals", {detail:{globals:{toolOutput:{title:"same"}, toolResponseMetadata:{mcp_tool_result:{_meta:{"lobu/mcp-app-snapshot-capability":"cap"}}}}}})));
  await waitFor(() => expect(bridge.callServerTool).toHaveBeenCalledWith({name:"restore_lobu_app_result", arguments:{snapshot_capability:"cap"}}));
  act(() => { for (const handler of bridge.listeners.get("toolresult") ?? []) handler({structuredContent:{title:"same"}}); });
  await act(async () => { resolveRestore({isError:false, structuredContent:{found:true, tool_name:"query_sdk", data:{title:"same"}, view_state:{"details.open":true}}}); await restore; });
  expect(screen.getByText("open:true")).toBeInTheDocument();
});

